FROM penguins |> WHERE body_mass_g IS NOT NULL |> EXTEND lump(species, n => 1) OVER () AS species_lump |> AGGREGATE count(*) AS n GROUP BY island, species_lump |> EXTEND stack(n) OVER (PARTITION BY island ORDER BY species_lump.other IS NOT NULL DESC NULLS FIRST, species_lump.weight ASC NULLS FIRST, species_lump.value DESC NULLS FIRST, n ASC NULLS LAST) AS n_stack |> AGGREGATE bar(x => island, y => scaled(n_stack, title => 'count(*)'), color => scaled(species_lump, title => 'species')) AS chart
